import json
import html
import time
import re
import hashlib

raw = r'''$exec'''

try:
    incoming = json.loads(raw)
except Exception:
    incoming = {}

def parse_json_if_string(value):
    if isinstance(value, str):
        try:
            return json.loads(value)
        except Exception:
            return value
    return value

incoming = parse_json_if_string(incoming)

def first_dict(*items):
    for item in items:
        item = parse_json_if_string(item)
        if isinstance(item, dict):
            return item
    return {}

def get_path(obj, path, default=None):
    cur = obj
    for key in path:
        if not isinstance(cur, dict):
            return default
        cur = parse_json_if_string(cur.get(key))
    return cur if cur not in [None, ""] else default

def safe(value, default="Unknown"):
    if value is None or value == "":
        return default
    return html.escape(str(value))

def plain(value, default="Unknown"):
    if value is None or value == "":
        return default
    return str(value)

def clean_tag(value):
    value = str(value)
    value = re.sub(r"[^a-zA-Z0-9_.:-]+", "-", value)
    return value.strip("-")[:120] or "unknown"

def first_value(*values, default="Unknown"):
    for value in values:
        value = parse_json_if_string(value)
        if value not in [None, "", "null", "None", "Unknown", "unknown", []]:
            return value
    return default

def regex_value(text, key):
    if not text:
        return None
    match = re.search(rf"\b{re.escape(key)}=([^\s]+)", str(text))
    return match.group(1) if match else None

def regex_first(text, patterns):
    if not text:
        return None
    for pattern in patterns:
        match = re.search(pattern, str(text), re.IGNORECASE)
        if match:
            return match.group(1)
    return None

def find_hash(text):
    if not text:
        return None

    text = str(text)

    # SHA256
    match = re.search(r"\b[a-fA-F0-9]{64}\b", text)
    if match:
        return match.group(0)

    # SHA1
    match = re.search(r"\b[a-fA-F0-9]{40}\b", text)
    if match:
        return match.group(0)

    # MD5
    match = re.search(r"\b[a-fA-F0-9]{32}\b", text)
    if match:
        return match.group(0)

    return None

def find_url(text):
    if not text:
        return None
    match = re.search(r"https?://[^\s\"'<>]+", str(text), re.IGNORECASE)
    return match.group(0) if match else None

def find_domain(text):
    if not text:
        return None

    text = str(text)

    # Avoid treating IPs as domains
    candidates = re.findall(
        r"\b(?:[a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}\b",
        text
    )

    ignore = {
        "thehive.local",
        "wazuh.local",
        "localhost.localdomain"
    }

    for candidate in candidates:
        candidate = candidate.strip(".").lower()
        if candidate not in ignore:
            return candidate

    return None

def find_file_path(text):
    if not text:
        return None

    text = str(text)

    patterns = [
        r"((?:[A-Za-z]:\\|\\\\)[^\s\"']+)",
        r"((?:/home|/tmp|/var|/opt|/usr|/etc|/root|/dev/shm)[^\s\"']+)",
        r"(?:file|path|filepath|file_path|target_path|Image|TargetFilename)[=:]\s*([^\s\"']+)"
    ]

    return regex_first(text, patterns)

def find_process_name(text):
    if not text:
        return None

    patterns = [
        r"(?:process_name|process|Image|ParentImage|CommandLine|cmdline)[=:]\s*[\"']?([^\"'\s]+)",
        r"\b(powershell\.exe|cmd\.exe|wscript\.exe|cscript\.exe|rundll32\.exe|regsvr32\.exe|mshta\.exe|python(?:3)?|bash|sh|nc|netcat|curl|wget|nmap)\b"
    ]

    return regex_first(text, patterns)

def find_command_line(text):
    if not text:
        return None

    patterns = [
        r"(?:command_line|cmdline|CommandLine|cmd)[=:]\s*[\"']?(.{5,500})",
        r"(powershell(?:\.exe)?\s+.{5,500})",
        r"(cmd(?:\.exe)?\s+/c\s+.{5,500})"
    ]

    value = regex_first(text, patterns)

    if value:
        return value.strip().strip('"').strip("'")[:500]

    return None

def find_username(text):
    if not text:
        return None

    patterns = [
        r"(?:user|username|dstuser|srcuser|account|win\.eventdata\.targetUserName)[=:]\s*([^\s\"']+)",
        r"for user\s+([^\s\"']+)",
        r"user\s+'([^']+)'"
    ]

    return regex_first(text, patterns)

def is_known(value):
    return str(value) not in ["", "Unknown", "unknown", "null", "None", "N/A"]

# ============================================================
# Locate Wazuh alert object
# ============================================================

alert = first_dict(
    incoming.get("alert") if isinstance(incoming, dict) else None,
    incoming.get("wazuh_alert") if isinstance(incoming, dict) else None,
    incoming.get("wazuh") if isinstance(incoming, dict) else None,
    incoming.get("event") if isinstance(incoming, dict) else None,
    incoming.get("original") if isinstance(incoming, dict) else None,
    get_path(incoming, ["body", "alert"]),
    get_path(incoming, ["body", "wazuh_alert"]),
    get_path(incoming, ["body", "event"]),
    incoming.get("body") if isinstance(incoming, dict) else None,
    incoming
)

alert = first_dict(
    alert.get("alert") if isinstance(alert, dict) else None,
    alert.get("wazuh_alert") if isinstance(alert, dict) else None,
    alert.get("original") if isinstance(alert, dict) else None,
    alert
)

rule = alert.get("rule", {}) if isinstance(alert, dict) else {}
agent = alert.get("agent", {}) if isinstance(alert, dict) else {}
data = alert.get("data", {}) if isinstance(alert, dict) else {}
manager = alert.get("manager", {}) if isinstance(alert, dict) else {}
decoder = alert.get("decoder", {}) if isinstance(alert, dict) else {}
predecoder = alert.get("predecoder", {}) if isinstance(alert, dict) else {}

full_log = (
    alert.get("full_log")
    or alert.get("message")
    or alert.get("log")
    or incoming.get("full_log") if isinstance(incoming, dict) else ""
)

if isinstance(full_log, dict):
    full_log = json.dumps(full_log)

full_context = json.dumps(alert, ensure_ascii=False) + "\n" + plain(full_log, "")

# ============================================================
# Rule / Agent
# ============================================================

rule_id = str(first_value(
    rule.get("id"),
    alert.get("rule_id"),
    incoming.get("rule_id") if isinstance(incoming, dict) else None,
    default="Unknown"
))

rule_desc = first_value(
    rule.get("description"),
    rule.get("title"),
    alert.get("description"),
    incoming.get("description") if isinstance(incoming, dict) else None,
    default="Unknown"
)

try:
    level = int(first_value(
        rule.get("level"),
        alert.get("level"),
        incoming.get("level") if isinstance(incoming, dict) else 0,
        default=0
    ))
except Exception:
    level = 0

rule_groups = rule.get("groups", [])
if not isinstance(rule_groups, list):
    rule_groups = [str(rule_groups)]

mitre = rule.get("mitre", {})
mitre_ids = []
mitre_tactics = []
mitre_techniques = []

if isinstance(mitre, dict):
    mitre_ids = mitre.get("id", []) or []
    mitre_tactics = mitre.get("tactic", []) or []
    mitre_techniques = mitre.get("technique", []) or []

if not isinstance(mitre_ids, list):
    mitre_ids = [str(mitre_ids)]
if not isinstance(mitre_tactics, list):
    mitre_tactics = [str(mitre_tactics)]
if not isinstance(mitre_techniques, list):
    mitre_techniques = [str(mitre_techniques)]

agent_id = first_value(
    agent.get("id"),
    alert.get("agent_id"),
    incoming.get("agent_id") if isinstance(incoming, dict) else None,
    default="Unknown"
)

agent_name = first_value(
    agent.get("name"),
    predecoder.get("hostname"),
    alert.get("agent_name"),
    incoming.get("agent_name") if isinstance(incoming, dict) else None,
    default="Unknown"
)

agent_ip = first_value(
    agent.get("ip"),
    alert.get("agent_ip"),
    incoming.get("agent_ip") if isinstance(incoming, dict) else None,
    default="Unknown"
)

manager_name = manager.get("name", "Unknown") if isinstance(manager, dict) else "Unknown"

# ============================================================
# Network / C2 / Web observables
# ============================================================

srcip = first_value(
    data.get("srcip"),
    data.get("src_ip"),
    data.get("source_ip"),
    data.get("src"),
    data.get("win", {}).get("eventdata", {}).get("ipAddress") if isinstance(data.get("win"), dict) else None,
    alert.get("srcip"),
    incoming.get("srcip") if isinstance(incoming, dict) else None,
    regex_value(full_log, "SRC"),
    default="Unknown"
)

dstip = first_value(
    data.get("dstip"),
    data.get("dst_ip"),
    data.get("destination_ip"),
    data.get("dst"),
    alert.get("dstip"),
    incoming.get("dstip") if isinstance(incoming, dict) else None,
    regex_value(full_log, "DST"),
    default="Unknown"
)

srcport = first_value(
    data.get("srcport"),
    data.get("src_port"),
    data.get("source_port"),
    regex_value(full_log, "SPT"),
    default="Unknown"
)

dstport = first_value(
    data.get("dstport"),
    data.get("dst_port"),
    data.get("destination_port"),
    regex_value(full_log, "DPT"),
    default="Unknown"
)

protocol = first_value(
    data.get("protocol"),
    data.get("proto"),
    regex_value(full_log, "PROTO"),
    default="Unknown"
)

action = first_value(
    data.get("action"),
    data.get("disposition"),
    alert.get("action"),
    regex_value(full_log, "ACTION"),
    default="Unknown"
)

url = first_value(
    data.get("url"),
    data.get("uri"),
    data.get("request"),
    data.get("http", {}).get("url") if isinstance(data.get("http"), dict) else None,
    find_url(full_context),
    default="Unknown"
)

domain = first_value(
    data.get("domain"),
    data.get("hostname"),
    data.get("dns", {}).get("question", {}).get("name") if isinstance(data.get("dns"), dict) else None,
    data.get("query"),
    data.get("url"),
    alert.get("domain"),
    incoming.get("domain") if isinstance(incoming, dict) else None,
    find_domain(url),
    find_domain(full_context),
    default="Unknown"
)

http_method = first_value(
    data.get("method"),
    data.get("http_method"),
    data.get("http", {}).get("request", {}).get("method") if isinstance(data.get("http"), dict) else None,
    regex_first(full_context, [r"(?:method|http_method)[=:]\s*([A-Z]+)"]),
    default="Unknown"
)

http_status = first_value(
    data.get("status"),
    data.get("status_code"),
    data.get("http_status"),
    data.get("http", {}).get("response", {}).get("status_code") if isinstance(data.get("http"), dict) else None,
    regex_first(full_context, [r"(?:status|status_code|http_status)[=:]\s*(\d{3})"]),
    default="Unknown"
)

dns_query = first_value(
    data.get("dns_query"),
    data.get("query"),
    data.get("dns", {}).get("question", {}).get("name") if isinstance(data.get("dns"), dict) else None,
    domain,
    default="Unknown"
)

# ============================================================
# Malware / endpoint observables
# ============================================================

win_eventdata = {}
if isinstance(data.get("win"), dict):
    win_eventdata = data.get("win", {}).get("eventdata", {}) or {}

file_name = first_value(
    data.get("file"),
    data.get("filename"),
    data.get("file_name"),
    data.get("target_filename"),
    win_eventdata.get("targetFilename"),
    regex_first(full_context, [
        r"(?:file|filename|file_name)[=:]\s*([^\s\"']+)",
        r"([a-zA-Z0-9_.-]+\.(?:exe|dll|ps1|bat|vbs|js|jar|sh|py|elf|bin|scr))"
    ]),
    default="Unknown"
)

file_path = first_value(
    data.get("file_path"),
    data.get("filepath"),
    data.get("path"),
    data.get("target_path"),
    win_eventdata.get("image"),
    win_eventdata.get("targetFilename"),
    find_file_path(full_context),
    default="Unknown"
)

file_hash = first_value(
    data.get("hash"),
    data.get("file_hash"),
    data.get("sha256"),
    data.get("sha1"),
    data.get("md5"),
    win_eventdata.get("hashes"),
    find_hash(full_context),
    default="Unknown"
)

md5 = first_value(
    data.get("md5"),
    regex_first(full_context, [r"\bMD5=([a-fA-F0-9]{32})\b", r"\bmd5[=:]\s*([a-fA-F0-9]{32})\b"]),
    default="Unknown"
)

sha1 = first_value(
    data.get("sha1"),
    regex_first(full_context, [r"\bSHA1=([a-fA-F0-9]{40})\b", r"\bsha1[=:]\s*([a-fA-F0-9]{40})\b"]),
    default="Unknown"
)

sha256 = first_value(
    data.get("sha256"),
    regex_first(full_context, [r"\bSHA256=([a-fA-F0-9]{64})\b", r"\bsha256[=:]\s*([a-fA-F0-9]{64})\b"]),
    default="Unknown"
)

process_name = first_value(
    data.get("process"),
    data.get("process_name"),
    data.get("program_name"),
    win_eventdata.get("image"),
    find_process_name(full_context),
    default="Unknown"
)

parent_process = first_value(
    data.get("parent_process"),
    data.get("parent_process_name"),
    win_eventdata.get("parentImage"),
    default="Unknown"
)

command_line = first_value(
    data.get("command"),
    data.get("cmd"),
    data.get("cmdline"),
    data.get("command_line"),
    win_eventdata.get("commandLine"),
    find_command_line(full_context),
    default="Unknown"
)

username = first_value(
    data.get("user"),
    data.get("username"),
    data.get("srcuser"),
    data.get("dstuser"),
    data.get("account"),
    win_eventdata.get("targetUserName"),
    win_eventdata.get("subjectUserName"),
    find_username(full_context),
    default="Unknown"
)

# ============================================================
# Alert metadata
# ============================================================

alert_id = str(first_value(
    alert.get("id"),
    incoming.get("id") if isinstance(incoming, dict) else None,
    default="N/A"
))

source = first_value(
    incoming.get("source") if isinstance(incoming, dict) else None,
    alert.get("location"),
    default="wazuh"
)

location = alert.get("location", "Unknown")

# ============================================================
# VirusTotal enrichment
# ============================================================

vt = (
    get_path(incoming, ["enrichment", "virustotal"], {})
    or get_path(alert, ["enrichment", "virustotal"], {})
    or {}
)

vt_results = vt.get("results", {}) if isinstance(vt, dict) else {}
vt_enabled = bool(vt.get("enabled", False)) if isinstance(vt, dict) else False

vt_malicious = 0
vt_suspicious = 0
vt_harmless = 0
vt_undetected = 0

for _, result in vt_results.items():
    body = result.get("body", {}) or {}
    attrs = body.get("data", {}).get("attributes", {}) if isinstance(body, dict) else {}
    stats = attrs.get("last_analysis_stats", {}) or {}

    vt_malicious += int(stats.get("malicious", 0) or 0)
    vt_suspicious += int(stats.get("suspicious", 0) or 0)
    vt_harmless += int(stats.get("harmless", 0) or 0)
    vt_undetected += int(stats.get("undetected", 0) or 0)

# ============================================================
# Alert type guess
# ============================================================

combined = f"{rule_desc} {' '.join(rule_groups)} {full_context}".lower()

if any(x in combined for x in ["nmap", "port scan", "scan detected", "recon", "reconnaissance"]):
    alert_type_guess = "scan"
elif any(x in combined for x in ["malware", "virus", "trojan", "ransomware", "clamav", "yara", "maldet", "infected"]):
    alert_type_guess = "malware"
elif any(x in combined for x in ["c2", "command and control", "beacon", "callback", "dns tunnel", "botnet"]):
    alert_type_guess = "c2"
elif any(x in combined for x in ["brute force", "authentication failure", "failed login", "invalid user", "ssh", "rdp"]):
    alert_type_guess = "auth"
elif any(x in combined for x in ["sql injection", "xss", "directory traversal", "web attack", "http", "apache", "nginx"]):
    alert_type_guess = "web_attack"
else:
    alert_type_guess = "generic"

# ============================================================
# SOC scoring
# ============================================================

score = level

if vt_malicious > 0:
    score += 5

if vt_suspicious > 0:
    score += 2

if is_known(srcip):
    score += 1

if is_known(dstip):
    score += 1

if is_known(dstport):
    score += 1

if alert_type_guess in ["malware", "c2"]:
    score += 2

if score >= 15:
    severity = "CRITICAL"
    icon = "🔥"
    thehive_severity = 4
elif score >= 10:
    severity = "HIGH"
    icon = "🚨"
    thehive_severity = 3
elif score >= 5:
    severity = "MEDIUM"
    icon = "⚠️"
    thehive_severity = 2
else:
    severity = "LOW"
    icon = "ℹ️"
    thehive_severity = 1

timestamp = time.strftime("%Y%m%d-%H%M%S", time.gmtime())
case_id = f"SOC-{timestamp}-{clean_tag(rule_id)}-{clean_tag(alert_id)}"

# ============================================================
# Simple fallback Telegram message
# AI node will replace this with smarter Telegram text
# ============================================================

telegram_message = f"""{icon} <b>SOCaaS Alert</b>

<b>Severity:</b> <code>{safe(severity)}</code>
<b>Case ID:</b> <code>{safe(case_id)}</code>
<b>Type:</b> <code>{safe(alert_type_guess)}</code>

<b>Agent:</b> <code>{safe(agent_name)}</code> / <code>{safe(agent_ip)}</code>
<b>Rule:</b> <code>{safe(rule_id)}</code> - {safe(rule_desc)}

<i>Wazuh → Shuffle → Email/TheHive</i>
"""

# ============================================================
# Email body with generic recommended actions.
# AI node will replace only the recommended section.
# ============================================================

email_subject = f"{icon} [SOCaaS][{severity}] Rule {rule_id} - {agent_name}"

email_body = f"""{icon} SOCaaS Security Alert

🆔 Case
• Case ID: {case_id}
• Severity: {severity}
• SOC Score: {score}
• Alert Type Guess: {alert_type_guess}

💻 Agent
• Name: {agent_name}
• IP: {agent_ip}
• ID: {agent_id}

📜 Rule
• ID: {rule_id}
• Wazuh Level: {level}
• Description: {rule_desc}
• Groups: {", ".join(rule_groups)}
• MITRE IDs: {", ".join(mitre_ids)}
• MITRE Tactics: {", ".join(mitre_tactics)}
• MITRE Techniques: {", ".join(mitre_techniques)}

🔎 Network / C2 / Web Observables
• Source IP: {srcip}
• Destination IP: {dstip}
• Source Port: {srcport}
• Destination Port: {dstport}
• Protocol: {protocol}
• Action: {action}
• Domain: {domain}
• URL: {url}
• DNS Query: {dns_query}
• HTTP Method: {http_method}
• HTTP Status: {http_status}

🧬 Malware / Endpoint Observables
• File Name: {file_name}
• File Path: {file_path}
• File Hash: {file_hash}
• MD5: {md5}
• SHA1: {sha1}
• SHA256: {sha256}
