• Parent Process: {parent_process}
• Command Line: {command_line}
• Username: {username}

🧪 VirusTotal
• Enabled: {vt_enabled}
• Malicious: {vt_malicious}
• Suspicious: {vt_suspicious}
• Harmless: {vt_harmless}
• Undetected: {vt_undetected}

🚨 Alert
• Alert ID: {alert_id}
• Source: {source}
• Location: {location}
• Manager: {manager_name}

🧾 Raw Log
{plain(full_log, "N/A")}

🛠️ Recommended Analyst Actions
1. Review the Wazuh alert details.
2. Validate the affected asset and observable fields.
3. Check related alerts involving the same source, destination, user, process, file, hash, domain, or URL.
4. Review relevant endpoint, firewall, DNS, proxy, web, or authentication logs.
5. Escalate if malicious activity is confirmed.

🔁 Pipeline
Wazuh → Pipeline Gateway → VirusTotal → Shuffle → Telegram/Email → TheHive
"""

# ============================================================
# Mailtrap payload
# ============================================================

mailtrap_payload = {
    "from": {
        "email": "hello@demomailtrap.co",
        "name": "SOCaaS Lab"
    },
    "to": [
        {
            "email": "khalil.hamidani@univ-alger.dz",
            "name": "Khalil Hamidani"
        }
    ],
    "subject": email_subject,
    "text": email_body,
    "category": "SOCaaS Alert"
}

# ============================================================
# TheHive payload
# ============================================================

thehive_tags = [
    "socaas",
    "shuffle",
    "wazuh",
    severity.lower(),
    f"type-{clean_tag(alert_type_guess)}",
    f"rule-{clean_tag(rule_id)}"
]

if is_known(srcip):
    thehive_tags.append(f"srcip-{clean_tag(srcip)}")

if is_known(dstip):
    thehive_tags.append(f"dstip-{clean_tag(dstip)}")

if is_known(dstport):
    thehive_tags.append(f"dpt-{clean_tag(dstport)}")

if is_known(protocol):
    thehive_tags.append(f"proto-{clean_tag(protocol)}")

if is_known(domain):
    thehive_tags.append(f"domain-{clean_tag(domain)}")

if is_known(file_hash):
    thehive_tags.append(f"hash-{clean_tag(file_hash)}")

if is_known(username):
    thehive_tags.append(f"user-{clean_tag(username)}")

thehive_case_payload = {
    "title": f"[SOCaaS][{severity}][{alert_type_guess}] Rule {rule_id} - {agent_name}",
    "description": email_body,
    "severity": thehive_severity,
    "tlp": 2,
    "pap": 2,
    "tags": thehive_tags,
    "flag": False
}

# ============================================================
# Output
# ============================================================

output = {
    "status": "ready",
    "case_id": case_id,
    "severity": severity,
    "score": score,
    "thehive_severity": thehive_severity,
    "alert_type_guess": alert_type_guess,

    "agent": agent_name,
    "agent_id": agent_id,
    "agent_ip": agent_ip,

    "rule_id": rule_id,
    "rule_desc": rule_desc,
