    "level": level,

    "mitre_ids": mitre_ids,
    "mitre_tactics": mitre_tactics,
    "mitre_techniques": mitre_techniques,

    "srcip": srcip,
    "dstip": dstip,
    "srcport": srcport,
    "dstport": dstport,
    "protocol": protocol,
    "action": action,
    "domain": domain,
    "url": url,
    "dns_query": dns_query,
    "http_method": http_method,
    "http_status": http_status,

    "file_name": file_name,
    "file_path": file_path,
    "file_hash": file_hash,
    "md5": md5,
    "sha1": sha1,
    "sha256": sha256,
    "process_name": process_name,
    "parent_process": parent_process,
    "command_line": command_line,
    "username": username,

    "alert_id": alert_id,
    "source": source,
